<script setup lang="ts">
import {ref} from 'vue'
import {state} from '../store'
import {sources,targets,targetLabel,newRoute,defaultMpeRoutes,type Key,type Route} from '../model'
import Knob from './Knob.vue'
import ExpressionCurve from './ExpressionCurve.vue'
import ZoneEditor from './ZoneEditor.vue'
const props=defineProps<{binding:Key}>()
const folded=ref(false),zonesFolded=ref(false)
const surfaceNames=['STRIKE','GLIDE','SLIDE','PRESS','LIFT']
function add(){if(props.binding.routes.length+state.patch.globalRoutes.length>=16){state.error='Each key supports 16 mappings, including global controllers.';return}props.binding.routes.push(newRoute())}
function range(route:Route){return targets.find(t=>t[0]===route.target)??targets[0]}
function retarget(route:Route){const r=newRoute(route.source,route.target);route.min=r.min;route.max=r.max}
const format=(v:number)=>Math.abs(v)>=1000?`${(v/1000).toFixed(1)}k`:Number(v.toFixed(2)).toString()
</script>
<template><div class="expression-modules">
<section class="ssb-module expression-module" :class="{folded}"><h4><button class="ssb-fold-title" :aria-expanded="!folded" @click="folded=!folded">EXPRESSION <span>{{folded?'◀':'▼'}}</span></button><span class="module-count">{{binding.routes.length}} ROUTES</span><button class="ssb-chip" title="Map all five MPE surfaces" @click="binding.routes=defaultMpeRoutes()">AUTO</button><button class="ssb-chip" aria-label="Add expression mapping" @click="add">＋</button><button class="ssb-chip" :class="{on:state.bindSource>=0}" :title="state.bindSource>=0?'Click a sound knob to bind this surface':'Cycle to a surface, then click a sound knob'" @click="state.bindSource=state.bindSource===4?-1:state.bindSource+1">BIND {{state.bindSource<0?'OFF':surfaceNames[state.bindSource]}}</button></h4>
<div v-show="!folded" class="expression-content"><div class="expression-routes"><div v-for="(route,i) in binding.routes" :key="i" class="expression-route"><div class="expression-route-top"><button class="ssb-chip surface-enum" :aria-label="`Expression source: ${sources[route.source]}`" title="Click to cycle MPE surface" @click="route.source=(route.source+1)%5">{{surfaceNames[route.source]}} ▸</button><span class="route-arrow">→</span><select v-model="route.target" class="ssb-enum" aria-label="Sound parameter" @change="retarget(route)"><option v-for="target in targets" :key="target[0]" :value="target[0]">{{targetLabel(target[0])}}</option></select><button class="ssb-chip route-remove" aria-label="Remove mapping" @click="binding.routes.splice(i,1)">×</button></div><div class="expression-dials"><Knob v-model="route.min" label="FROM" :min="range(route)[1]" :max="range(route)[2]" :default="range(route)[1]" :bipolar="range(route)[1]<0" :size="28" :format="format"/><Knob v-model="route.max" label="TO" :min="range(route)[1]" :max="range(route)[2]" :default="range(route)[2]" :bipolar="range(route)[1]<0" :size="28" :format="format"/><Knob v-model="route.smoothing" label="SLEW" :max="1000" :default="8" curve="pow2" :size="28" :format="v=>`${Math.round(v)}ms`"/><ExpressionCurve v-model="route.curve" :label="`${surfaceNames[route.source]} to ${route.target} curve`"/></div></div></div><p class="module-hint">{{state.bindSource>=0?`Click a sound knob to bind ${surfaceNames[state.bindSource]}.`:'Drag a curve to shape response · FROM / TO set its range · SLEW smooths movement'}}</p></div>
</section>
<section class="ssb-module expression-zones" :class="{folded:zonesFolded}"><h4><button class="ssb-fold-title" :aria-expanded="!zonesFolded" @click="zonesFolded=!zonesFolded">KEY ZONES <span>{{zonesFolded?'◀':'▼'}}</span></button><button class="ssb-chip on" aria-label="Zone control source" title="Click to cycle the zone control surface" @click="binding.zoneSource=(binding.zoneSource+1)%4">{{surfaceNames[binding.zoneSource]}} ▸</button></h4><ZoneEditor v-show="!zonesFolded" :zones="binding.zones" :scope="String(binding.note)" compact/></section>
</div></template>
<style scoped>
.expression-modules{display:flex;flex-wrap:wrap;align-items:stretch;gap:4px;margin-top:4px}.expression-module{flex:1 1 530px;min-width:0}.expression-zones{flex:1 1 250px;min-width:0;max-width:340px;display:flex;flex-direction:column}.expression-zones :deep(.zone-control.compact){height:auto;min-height:110px;flex:1}.expression-routes{display:grid;grid-template-columns:repeat(auto-fit,minmax(235px,1fr));gap:4px}.expression-route{min-width:0;border:1px solid color-mix(in srgb,var(--text) 8%,transparent);border-radius:3px;padding:5px;background:#0002}.expression-route-top{display:flex;align-items:center;gap:4px;margin-bottom:6px}.expression-route-top select{min-width:0;width:0;flex:1}.surface-enum{color:var(--c-secondary)!important}.route-arrow{color:var(--text-mute);font-size:10px}.expression-dials{display:flex;justify-content:space-around;gap:3px;align-items:center}.module-hint{margin:6px 2px 2px;color:var(--text-mute);font-size:9px}.module-count{font:9px monospace;color:var(--text-mute);margin-right:auto}.expression-module.folded{flex:0 1 auto;align-self:flex-start}.expression-zones.folded{flex:0 1 auto;align-self:flex-start}.expression-content{padding-top:3px}
</style>
